import type { GeneratedSdkFile, SdkGenerationOptions, SdkTargetStrategy } from './contract';

const THREE_MOD = 'three';

const THREE_HEADER = [
  '// Generated by Ashfox Runtime SDK (Three.js) — zero external runtime dependencies beyond three.',
  `import * as THREE from '${THREE_MOD}';`,
  `import { GLTFLoader, type GLTF } from '${THREE_MOD}/examples/jsm/loaders/GLTFLoader.js';`,
  `import { MeshoptDecoder } from '${THREE_MOD}/examples/jsm/libs/meshopt_decoder.module.js';`,
  '',
  `export type AshfoxCueKind = 'vfx' | 'sound' | 'event';`,
  `export interface AshfoxCueRecord { readonly kind: AshfoxCueKind; readonly time: number; readonly endTime?: number; readonly name: string; readonly anchor?: string; readonly payload?: Readonly<Record<string, string | number | boolean>>; }`,
  `export interface AshfoxCueEvent { readonly name: string; readonly kind: AshfoxCueKind; readonly time: number; readonly anchor?: string; readonly worldPosition: readonly [number, number, number]; readonly worldDirection: readonly [number, number, number]; readonly data: Readonly<Record<string, string | number | boolean>>; }`,
  'export type AshfoxCueCallback = (cue: AshfoxCueEvent) => void;',
  `export type AshfoxCollider = | { readonly shape: 'capsule'; readonly axis: 'y'; readonly center: readonly [number, number, number]; readonly radius: number; readonly height: number } | { readonly shape: 'box'; readonly center: readonly [number, number, number]; readonly size: readonly [number, number, number]; readonly min: readonly [number, number, number]; readonly max: readonly [number, number, number] };`,
  `export type AshfoxHitZoneShape = 'box' | 'capsule' | 'sphere';`,
  `export type AshfoxDamageStateKind = 'intact' | 'damaged' | 'destroyed';`,
  `export interface AshfoxHitZone { readonly id: string; readonly bone: string; readonly shape: AshfoxHitZoneShape; readonly multiplier: number; readonly tag: string; readonly center: readonly [number, number, number]; readonly localCenter: readonly [number, number, number]; readonly size?: readonly [number, number, number]; readonly min?: readonly [number, number, number]; readonly max?: readonly [number, number, number]; readonly radius?: number; readonly height?: number; }`,
  `export interface AshfoxDamageStateMeta { readonly state: AshfoxDamageStateKind; readonly baseId?: string; readonly breakVfx?: string; readonly breakSound?: string; readonly variants?: Readonly<Record<string, string>>; }`,
  `export interface AshfoxColliderSet { readonly profile: 'creature' | 'prop' | 'block'; readonly aabb: { readonly min: readonly [number, number, number]; readonly max: readonly [number, number, number] }; readonly colliders: readonly AshfoxCollider[]; readonly hitzones?: readonly AshfoxHitZone[]; }`,
  `export interface AshfoxHookAnchor { readonly id: string; readonly schema: string; readonly position: readonly [number, number, number]; readonly normal: readonly [number, number, number]; readonly rotation: readonly [number, number, number]; readonly bone?: string; readonly props: Readonly<Record<string, unknown>>; }`,
  `export interface AshfoxHooksDoc { readonly schemaVersion: number; readonly assetId: string; readonly anchors: readonly AshfoxHookAnchor[]; readonly colliders?: AshfoxColliderSet; readonly damageState?: AshfoxDamageStateMeta; }`,
  `export interface AshfoxSoundVariant { readonly id: string; readonly file: string; readonly durationSeconds?: number; readonly sampleRate?: number; readonly channels?: number; readonly playback?: { readonly kind: string; readonly startFrame?: number; readonly endFrame?: number }; readonly loopStartSample?: number; readonly loopEndSample?: number; }`,
  `export interface AshfoxManifestAsset { readonly id: string; readonly kind: 'model' | 'structure' | 'sprite' | 'sound' | 'vfx'; readonly model?: string; readonly image?: string; readonly hooks?: string; readonly vfxSpec?: string; readonly codec?: 'wav' | 'ogg'; readonly variants?: readonly AshfoxSoundVariant[]; readonly colliders?: AshfoxColliderSet; readonly damageState?: AshfoxDamageStateMeta; }`,
  'export interface AshfoxManifest { readonly format?: string; readonly version?: number; readonly baseUrl?: string; readonly assets: readonly AshfoxManifestAsset[]; }',
  'export interface AshfoxGltfLoaderLike { loadAsync(url: string): Promise<GLTF>; setMeshoptDecoder?(decoder: unknown): unknown; }',
  'export interface AshfoxVfxSpawnEvent { readonly id: string; readonly anchor?: string; readonly object: THREE.Object3D; }',
  'export interface AshfoxSoundPlayEvent { readonly id: string; readonly variant: AshfoxSoundVariant; readonly loopStart: number; readonly loopEnd: number; readonly loop: boolean; readonly object: THREE.Object3D; }',
  'export interface AshfoxRuntimeOptions {',
  '  readonly scene: THREE.Scene; readonly audioListener?: THREE.AudioListener; readonly manifestUrl?: string; readonly manifest?: AshfoxManifest;',
  '  readonly loader?: AshfoxGltfLoaderLike; readonly fetchFn?: typeof fetch; readonly decodeAudio?: (buf: ArrayBuffer) => Promise<AudioBuffer>;',
  '  readonly onVfxSpawn?: (ev: AshfoxVfxSpawnEvent) => void; readonly onSoundPlay?: (ev: AshfoxSoundPlayEvent) => void;',
  '}',
  'export interface AshfoxSpawnOptions { readonly position?: readonly [number, number, number] | THREE.Vector3; readonly rotation?: readonly [number, number, number] | THREE.Euler; readonly parent?: THREE.Object3D; }',
  'export interface AshfoxActor {',
  '  readonly id: string; readonly root: THREE.Object3D; readonly anchors: Readonly<Record<string, THREE.Object3D>>;',
  '  readonly colliders?: AshfoxColliderSet; readonly hooks?: AshfoxHooksDoc; readonly lod?: THREE.LOD;',
  '  readonly damageState: AshfoxDamageStateKind;',
  '  getAnchor(id: string): THREE.Object3D | undefined;',
  '  getHitZone(collider: unknown): AshfoxHitZone | undefined;',
  '  setDamageState(state: AshfoxDamageStateKind): Promise<void>;',
  '  equip(socket: string, assetId: string | null): Promise<AshfoxActor | null>;',
  '  play(clipName: string, opts?: { readonly loop?: boolean; readonly timeScale?: number }): THREE.AnimationAction | null;',
  '  stop(): void; update(dt: number): void; onCue(name: string, cb: AshfoxCueCallback): () => void; dispose(): void;',
  '}',
  'export interface AshfoxRuntime { spawn(id: string, opts?: AshfoxSpawnOptions): Promise<AshfoxActor>; update(dt: number): void; getManifest(): Promise<AshfoxManifest>; dispose(): void; }',
].join('\n');

const THREE_HELPERS = [
  'function resolveRelUrl(rel: string, base?: string): string {',
  '  if (!base || /^[a-z]+:/i.test(rel) || rel.startsWith("/")) return rel;',
  '  const idx = base.lastIndexOf("/");',
  '  return (idx >= 0 ? base.slice(0, idx + 1) : "") + rel;',
  '}',
  'function applyAshfoxMaterials(root: THREE.Object3D): void {',
  '  root.traverse((obj) => {',
  '    const mesh = obj as THREE.Mesh;',
  '    if (!mesh.isMesh || !mesh.material) return;',
  '    const mats = Array.isArray(mesh.material) ? mesh.material : [mesh.material];',
  '    for (const mat of mats) {',
  '      const ud = mat.userData as { ashfoxBlendMode?: string; KHR_materials_unlit?: unknown } | undefined;',
  '      if (ud?.ashfoxBlendMode === "additive") { mat.blending = THREE.AdditiveBlending; mat.transparent = true; mat.depthWrite = false; mat.needsUpdate = true; }',
  '      else if (ud?.ashfoxBlendMode === "premul") { mat.premultipliedAlpha = true; mat.transparent = true; mat.needsUpdate = true; }',
  '      if (ud?.KHR_materials_unlit !== undefined || mat.type === "MeshBasicMaterial") mat.toneMapped = false;',
  '    }',
  '  });',
  '}',
  'function buildLodGroup(root: THREE.Object3D): THREE.LOD | undefined {',
  '  const tiers: { tier: number; obj: THREE.Object3D; parent: THREE.Object3D }[] = [];',
  '  root.traverse((obj) => { const m = /_LOD([0-9]+)$/i.exec(obj.name); if (m && obj.parent) tiers.push({ tier: Number(m[1]), obj, parent: obj.parent }); });',
  '  if (tiers.length < 2) return undefined;',
  '  tiers.sort((a, b) => a.tier - b.tier);',
  '  const dists = (root.userData as { ashfox?: { lod?: { distances?: number[] } } })?.ashfox?.lod?.distances ?? [0, 18, 45];',
  '  const lod = new THREE.LOD(); lod.name = root.name ? `${root.name}_lod` : "ashfox_lod";',
  '  const host = tiers[0]!.parent;',
  '  tiers.forEach((t, i) => { lod.addLevel(t.obj, dists[t.tier] ?? dists[i] ?? i * 25); });',
  '  host.add(lod); return lod;',
  '}',
  'function collectAnchors(root: THREE.Object3D, hooks?: AshfoxHooksDoc): Record<string, THREE.Object3D> {',
  '  const anchors: Record<string, THREE.Object3D> = {}; const byName = new Map<string, THREE.Object3D>();',
  '  root.traverse((obj) => {',
  '    if (obj.name) byName.set(obj.name, obj);',
  '    const hook = (obj.userData as { ashfox?: { hook?: { kind?: string; id?: string } } })?.ashfox?.hook;',
  '    if (hook?.kind === "anchor" && hook.id) anchors[hook.id] = obj;',
  '    else if (obj.name.startsWith("anchor_")) anchors[obj.name.slice(7)] = obj;',
  '  });',
  '  for (const decl of hooks?.anchors ?? []) {',
  '    if (anchors[decl.id]) continue;',
  '    const marker = new THREE.Object3D(); marker.name = `anchor_${decl.id}`;',
  '    marker.position.set(decl.position[0] / 16, decl.position[1] / 16, decl.position[2] / 16);',
  '    ((decl.bone ? byName.get(decl.bone) : undefined) ?? root).add(marker); anchors[decl.id] = marker;',
  '  }',
  '  return anchors;',
  '}',
  'const SOCKET_BONE_FALLBACKS: Readonly<Record<string, readonly string[]>> = {',
  '  head_helm: ["head"], chest_armor: ["torso", "body"], back_cape: ["torso", "body"],',
  '  main_hand: ["right_arm", "weapon", "hand_r"], off_hand: ["left_arm", "hand_l"], mount_saddle: ["body", "torso"],',
  '};',
  'function findBoneObject(root: THREE.Object3D, names: readonly string[]): THREE.Object3D | undefined {',
  '  let found: THREE.Object3D | undefined;',
  '  root.traverse((obj) => {',
  '    if (found) return;',
  '    const aid = (obj.userData as { ashfoxId?: string } | undefined)?.ashfoxId;',
  '    if (names.includes(obj.name) || (aid && names.includes(aid))) found = obj;',
  '  });',
  '  return found;',
  '}',
  'function resolveSocketMount(root: THREE.Object3D, anchors: Record<string, THREE.Object3D>, socket: string): THREE.Object3D {',
  '  if (anchors[socket]) return anchors[socket]!;',
  '  const direct = findBoneObject(root, [socket, ...(SOCKET_BONE_FALLBACKS[socket] ?? [])]) ?? root;',
  '  const mount = new THREE.Object3D(); mount.name = `socket_${socket}`; direct.add(mount); anchors[socket] = mount; return mount;',
  '}',
  'function pointInHitZone(localPt: THREE.Vector3, hz: AshfoxHitZone): boolean {',
  '  const dx = localPt.x - hz.center[0]; const dy = localPt.y - hz.center[1]; const dz = localPt.z - hz.center[2];',
  '  if (hz.shape === "sphere") { const r = hz.radius ?? 0.25; return dx * dx + dy * dy + dz * dz <= r * r + 1e-5; }',
  '  if (hz.shape === "capsule") { const r = hz.radius ?? 0.25; const half = Math.max(0, (hz.height ?? r * 2) * 0.5 - r); const cy = Math.max(-half, Math.min(half, dy)); return dx * dx + (dy - cy) * (dy - cy) + dz * dz <= r * r + 1e-5; }',
  '  const sz = hz.size ?? [0.5, 0.5, 0.5];',
  '  return Math.abs(dx) <= sz[0] * 0.5 + 1e-5 && Math.abs(dy) <= sz[1] * 0.5 + 1e-5 && Math.abs(dz) <= sz[2] * 0.5 + 1e-5;',
  '}',
  'function matchHitZone(root: THREE.Object3D, hitzones: readonly AshfoxHitZone[] | undefined, collider: unknown): AshfoxHitZone | undefined {',
  '  if (!hitzones || hitzones.length === 0) return undefined;',
  '  if (typeof collider === "string") return hitzones.find((h) => h.id === collider || h.bone === collider || h.tag === collider || `hitzone_${h.id}` === collider);',
  '  if (!collider || typeof collider !== "object") return undefined;',
  '  const rec = collider as { object?: THREE.Object3D; point?: THREE.Vector3 | readonly [number, number, number]; isObject3D?: boolean };',
  '  const obj = rec.object ?? (rec.isObject3D ? (collider as THREE.Object3D) : undefined);',
  '  for (let cur: THREE.Object3D | null = obj ?? null; cur; cur = cur.parent) {',
  '    const hzUd = (cur.userData as { ashfox?: { hitzone?: { id?: string } }; ashfoxId?: string } | undefined);',
  '    const hid = hzUd?.ashfox?.hitzone?.id ?? (cur.name.startsWith("hitzone_") ? cur.name.slice(8) : undefined);',
  '    if (hid) { const hit = hitzones.find((h) => h.id === hid); if (hit) return hit; }',
  '    const bid = hzUd?.ashfoxId ?? cur.name;',
  '    const byBone = hitzones.filter((h) => h.bone === bid);',
  '    if (byBone.length === 1) return byBone[0];',
  '    if (cur === root) break;',
  '  }',
  '  const pt = new THREE.Vector3();',
  '  if (Array.isArray(rec.point)) pt.set(rec.point[0], rec.point[1], rec.point[2]);',
  '  else if (rec.point && "x" in rec.point) pt.copy(rec.point as THREE.Vector3);',
  '  else if (obj) { obj.updateWorldMatrix(true, false); obj.getWorldPosition(pt); }',
  '  else return undefined;',
  '  root.updateWorldMatrix(true, false); root.worldToLocal(pt);',
  '  return [...hitzones].sort((a, b) => b.multiplier - a.multiplier).find((h) => pointInHitZone(pt, h));',
  '}',
].join('\n');

const THREE_SERVICES = [
  'interface VfxInstance { root: THREE.Object3D; mixer: THREE.AnimationMixer; elapsed: number; duration: number; id: string; }',
  'function createServices(opts: AshfoxRuntimeOptions, getManifest: () => Promise<AshfoxManifest>, gltfLoader: AshfoxGltfLoaderLike) {',
  '  const vfxPool = new Map<string, VfxInstance[]>(); const activeVfx: VfxInstance[] = []; const audioBuffers = new Map<string, AudioBuffer>();',
  '  const fetchFn = opts.fetchFn ?? (typeof fetch === "function" && Boolean(opts.manifestUrl || opts.manifest?.baseUrl || typeof location !== "undefined") ? fetch : undefined);',
  '  const spawnVfx = async (id: string, anchor: THREE.Object3D): Promise<void> => {',
  '    const manifest = await getManifest();',
  '    const asset = manifest.assets.find((a) => a.id === id || a.id === `vfx.${id}`);',
  '    let inst = vfxPool.get(id)?.pop();',
  '    if (!inst) {',
  '      if (asset?.model) {',
  '        const gltf = await gltfLoader.loadAsync(resolveRelUrl(asset.model, manifest.baseUrl ?? opts.manifestUrl));',
  '        applyAshfoxMaterials(gltf.scene); const mixer = new THREE.AnimationMixer(gltf.scene); const clip = gltf.animations[0];',
  '        if (clip) mixer.clipAction(clip).play();',
  '        inst = { root: gltf.scene, mixer, elapsed: 0, duration: clip ? clip.duration : 0.6, id };',
  '      } else {',
  '        const fallback = new THREE.Group(); fallback.name = `vfx_${id}`;',
  '        inst = { root: fallback, mixer: new THREE.AnimationMixer(fallback), elapsed: 0, duration: 0.5, id };',
  '      }',
  '    }',
  '    inst.elapsed = 0; inst.root.visible = true; anchor.add(inst.root); activeVfx.push(inst);',
  '    opts.onVfxSpawn?.({ id, anchor: anchor.name, object: inst.root });',
  '  };',
  '  const playSound = async (id: string, anchor: THREE.Object3D): Promise<void> => {',
  '    const manifest = await getManifest();',
  '    const asset = manifest.assets.find((a) => a.id === id || a.id === `sfx.${id}`);',
  '    const variant = asset?.variants?.[0]; if (!variant) return;',
  '    const sr = variant.sampleRate ?? 48000; const loop = variant.playback?.kind === "loop";',
  '    const loopStart = (variant.loopStartSample ?? 0) / sr; const loopEnd = (variant.loopEndSample ?? 0) / sr;',
  '    opts.onSoundPlay?.({ id, variant, loopStart, loopEnd, loop, object: anchor });',
  '    if (!opts.audioListener) return;',
  '    const url = resolveRelUrl(variant.file, manifest.baseUrl ?? opts.manifestUrl); let buf = audioBuffers.get(url);',
  '    if (!buf && fetchFn) { const res = await fetchFn(url); if (res.ok) { const raw = await res.arrayBuffer(); buf = opts.decodeAudio ? await opts.decodeAudio(raw) : await opts.audioListener.context.decodeAudioData(raw); audioBuffers.set(url, buf); } }',
  '    if (!buf) return;',
  '    const audio = new THREE.PositionalAudio(opts.audioListener); audio.setBuffer(buf); audio.setLoop(loop);',
  '    if (loop && loopEnd > loopStart) { audio.setLoopStart(loopStart); audio.setLoopEnd(loopEnd); }',
  '    anchor.add(audio); audio.play();',
  '  };',
  '  const updateVfx = (dt: number): void => {',
  '    for (let i = activeVfx.length - 1; i >= 0; i -= 1) {',
  '      const inst = activeVfx[i]!; inst.elapsed += dt; inst.mixer.update(dt);',
  '      if (inst.elapsed >= inst.duration) { inst.root.visible = false; inst.root.removeFromParent(); activeVfx.splice(i, 1); const b = vfxPool.get(inst.id) ?? []; b.push(inst); vfxPool.set(inst.id, b); }',
  '    }',
  '  };',
  '  return { spawnVfx, playSound, updateVfx };',
  '}',
].join('\n');

const THREE_ACTOR_AND_RUNTIME = [
  'function createActorInstance(',
  '  id: string, gltf: GLTF, asset: AshfoxManifestAsset, hooks: AshfoxHooksDoc | undefined,',
  '  services: ReturnType<typeof createServices>, getManifest: () => Promise<AshfoxManifest>,',
  '  gltfLoader: AshfoxGltfLoaderLike, baseUrl: string | undefined,',
  '  spawnChild: (assetId: string, spawnOpts: AshfoxSpawnOptions) => Promise<AshfoxActor>,',
  '  onDispose: () => void,',
  '): AshfoxActor {',
  '  const root = gltf.scene; applyAshfoxMaterials(root);',
  '  const lod = buildLodGroup(root); let anchors = collectAnchors(root, hooks);',
  '  let mixer = new THREE.AnimationMixer(root); const listeners = new Map<string, Set<AshfoxCueCallback>>();',
  '  const equipped = new Map<string, AshfoxActor>();',
  '  let currentDamageState: AshfoxDamageStateKind = hooks?.damageState?.state ?? asset.damageState?.state ?? "intact";',
  '  let activeClips = gltf.animations;',
  '  const vPos = new THREE.Vector3(); const vDir = new THREE.Vector3();',
  '  let activeAction: THREE.AnimationAction | null = null; let activeClip: THREE.AnimationClip | null = null;',
  '  let activeCues: readonly AshfoxCueRecord[] = []; let clipTime = 0; let firstTick = true; let timeScale = 1; let isLoop = false;',
  '  const emitCue = (cue: AshfoxCueRecord): void => {',
  '    const anchorObj = (cue.anchor ? anchors[cue.anchor] : undefined) ?? root;',
  '    if (cue.kind === "vfx") { void services.spawnVfx(cue.name, anchorObj); return; }',
  '    if (cue.kind === "sound") { void services.playSound(cue.name, anchorObj); return; }',
  '    anchorObj.updateWorldMatrix(true, false); anchorObj.getWorldPosition(vPos); anchorObj.getWorldDirection(vDir);',
  '    const ev: AshfoxCueEvent = { name: cue.name, kind: cue.kind, time: cue.time, anchor: cue.anchor, worldPosition: [vPos.x, vPos.y, vPos.z], worldDirection: [vDir.x, vDir.y, vDir.z], data: cue.payload ?? {} };',
  '    for (const cb of listeners.get(cue.name) ?? []) cb(ev);',
  '    for (const cb of listeners.get("*") ?? []) cb(ev);',
  '  };',
  '  const fireWindow = (from: number, to: number, inclusive: boolean): void => {',
  '    for (const cue of activeCues) { if ((inclusive ? cue.time >= from : cue.time > from) && cue.time <= to) emitCue(cue); }',
  '  };',
  '  const colliders = hooks?.colliders ?? asset.colliders;',
  '  const actor: AshfoxActor = {',
  '    id, root, anchors, hooks, colliders, lod,',
  '    get damageState() { return currentDamageState; },',
  '    getAnchor: (name) => anchors[name],',
  '    getHitZone: (collider) => matchHitZone(root, colliders?.hitzones, collider),',
  '    async setDamageState(nextState) {',
  '      currentDamageState = nextState;',
  '      root.traverse((obj) => {',
  '        const m = /^(?:damage_|.+_)(intact|damaged|destroyed)$/.exec(obj.name);',
  '        if (m) obj.visible = m[1] === nextState;',
  '      });',
  '      const meta = hooks?.damageState ?? asset.damageState;',
  '      const manifest = await getManifest();',
  '      const baseId = meta?.baseId ?? id.replace(/_(intact|damaged|destroyed)$/, "");',
  '      const variantId = meta?.variants?.[nextState];',
  '      const target = manifest.assets.find((a) => a.id === variantId || (a.damageState?.baseId === baseId && a.damageState?.state === nextState) || a.id === `${baseId}_${nextState}`);',
  '      const targetMeta = target?.damageState ?? (meta?.state === nextState ? meta : undefined);',
  '      if (target?.model && target.id !== id) {',
  '        const nextGltf = await gltfLoader.loadAsync(resolveRelUrl(target.model, baseUrl));',
  '        applyAshfoxMaterials(nextGltf.scene);',
  '        const keepSockets = new Set(Object.keys(anchors).filter((k) => equipped.has(k)));',
  '        const saved = [...equipped.entries()].map(([s, ch]) => [s, ch.root] as const);',
  '        for (const [, chRoot] of saved) chRoot.removeFromParent();',
  '        for (const ch of [...root.children]) root.remove(ch);',
  '        for (const ch of [...nextGltf.scene.children]) root.add(ch);',
  '        activeClips = nextGltf.animations; mixer = new THREE.AnimationMixer(root);',
  '        anchors = collectAnchors(root, hooks);',
  '        for (const [s, chRoot] of saved) { if (keepSockets.has(s)) resolveSocketMount(root, anchors, s).add(chRoot); }',
  '      }',
  '      if (nextState !== "intact") {',
  '        if (targetMeta?.breakVfx) void services.spawnVfx(targetMeta.breakVfx, root);',
  '        if (targetMeta?.breakSound) void services.playSound(targetMeta.breakSound, root);',
  '      }',
  '      emitCue({ kind: "event", time: clipTime, name: "damage_state", payload: { state: nextState } });',
  '    },',
  '    async equip(socket, assetId) {',
  '      const prev = equipped.get(socket);',
  '      if (prev) { prev.dispose(); equipped.delete(socket); }',
  '      if (assetId === null) return null;',
  '      const mount = resolveSocketMount(root, anchors, socket);',
  '      const child = await spawnChild(assetId, { parent: mount });',
  '      equipped.set(socket, child); return child;',
  '    },',
  '    play(clipName, playOpts) {',
  '      const clip = activeClips.find((c) => c.name === clipName); if (!clip) return null;',
  '      activeAction?.stop(); activeClip = clip;',
  '      const rawCues = (clip.userData as { ashfoxCues?: AshfoxCueRecord[] } | undefined)?.ashfoxCues ?? [];',
  '      activeCues = [...rawCues].sort((a, b) => a.time - b.time);',
  '      isLoop = playOpts?.loop ?? (clip.userData as { ashfoxLoop?: string } | undefined)?.ashfoxLoop === "loop";',
  '      timeScale = playOpts?.timeScale ?? 1; clipTime = 0; firstTick = true;',
  '      activeAction = mixer.clipAction(clip); activeAction.setLoop(isLoop ? THREE.LoopRepeat : THREE.LoopOnce, Infinity);',
  '      activeAction.clampWhenFinished = !isLoop; activeAction.reset().play(); return activeAction;',
  '    },',
  '    stop() { activeAction?.stop(); activeAction = null; activeClip = null; activeCues = []; },',
  '    update(dt) {',
  '      if (dt < 0) return;',
  '      mixer.update(dt * timeScale); if (!activeClip) return;',
  '      const dur = Math.max(activeClip.duration, 0); const prev = clipTime; const next = prev + dt * timeScale;',
  '      if (isLoop && dur > 0) {',
  '        if (next >= dur) { fireWindow(prev, dur, firstTick); const wrapped = next % dur; fireWindow(0, wrapped, true); clipTime = wrapped; }',
  '        else { fireWindow(prev, next, firstTick); clipTime = next; }',
  '      } else { const clamped = dur > 0 ? Math.min(next, dur) : next; fireWindow(prev, clamped, firstTick); clipTime = clamped; }',
  '      firstTick = false;',
  '    },',
  '    onCue(name, cb) { const set = listeners.get(name) ?? new Set(); set.add(cb); listeners.set(name, set); return () => { set.delete(cb); }; },',
  '    dispose() { for (const ch of equipped.values()) ch.dispose(); equipped.clear(); activeAction?.stop(); mixer.stopAllAction(); root.removeFromParent(); listeners.clear(); onDispose(); },',
  '  };',
  '  return actor;',
  '}',
  'export function createAshfoxRuntime(opts: AshfoxRuntimeOptions): AshfoxRuntime {',
  '  const gltfLoader: AshfoxGltfLoaderLike = opts.loader ?? new GLTFLoader(); gltfLoader.setMeshoptDecoder?.(MeshoptDecoder);',
  '  const fetchFn = opts.fetchFn ?? (typeof fetch === "function" && Boolean(opts.manifestUrl || opts.manifest?.baseUrl || typeof location !== "undefined") ? fetch : undefined);',
  '  let manifestPromise: Promise<AshfoxManifest> | null = opts.manifest ? Promise.resolve(opts.manifest) : null;',
  '  const getManifest = (): Promise<AshfoxManifest> => {',
  '    if (manifestPromise) return manifestPromise;',
  '    if (!opts.manifestUrl || !fetchFn) return Promise.reject(new Error("Missing manifest or manifestUrl"));',
  '    manifestPromise = fetchFn(opts.manifestUrl).then((r) => { if (!r.ok) throw new Error(`HTTP ${r.status}`); return r.json() as Promise<AshfoxManifest>; });',
  '    return manifestPromise;',
  '  };',
  '  const services = createServices(opts, getManifest, gltfLoader); const actors = new Set<AshfoxActor>();',
  '  const spawn = async (id: string, spawnOpts?: AshfoxSpawnOptions): Promise<AshfoxActor> => {',
  '    const manifest = await getManifest(); const asset = manifest.assets.find((a) => a.id === id);',
  '    if (!asset || !asset.model) throw new Error(`Ashfox model asset not found: ${id}`);',
  '    const base = manifest.baseUrl ?? opts.manifestUrl; const gltf = await gltfLoader.loadAsync(resolveRelUrl(asset.model, base));',
  '    let hooks = (gltf.scene.userData as { ashfox?: { hooks?: AshfoxHooksDoc } } | undefined)?.ashfox?.hooks;',
  '    if (!hooks && asset.hooks && fetchFn) { const hr = await fetchFn(resolveRelUrl(asset.hooks, base)); if (hr.ok) hooks = (await hr.json()) as AshfoxHooksDoc; }',
  '    if (spawnOpts?.position) { const p = spawnOpts.position; Array.isArray(p) ? gltf.scene.position.set(p[0], p[1], p[2]) : gltf.scene.position.copy(p as THREE.Vector3); }',
  '    if (spawnOpts?.rotation) { const r = spawnOpts.rotation; Array.isArray(r) ? gltf.scene.rotation.set(r[0], r[1], r[2]) : gltf.scene.rotation.copy(r as THREE.Euler); }',
  '    (spawnOpts?.parent ?? opts.scene).add(gltf.scene);',
  '    const actor = createActorInstance(id, gltf, asset, hooks, services, getManifest, gltfLoader, base, spawn, () => actors.delete(actor)); actors.add(actor); return actor;',
  '  };',
  '  return {',
  '    spawn,',
  '    update(dt) { for (const actor of actors) actor.update(dt); services.updateVfx(dt); },',
  '    getManifest,',
  '    dispose() { for (const actor of [...actors]) actor.dispose(); actors.clear(); },',
  '  };',
  '}',
].join('\n');

const emitThreeSdk = (options?: SdkGenerationOptions): readonly GeneratedSdkFile[] => {
  const manifestBanner = options?.manifest
    ? `export const ASHFOX_GENERATED_ASSET_IDS = ${JSON.stringify(
        options.manifest.assets.map((a) => a.id),
      )} as const;\n`
    : '';
  const content = [
    THREE_HEADER,
    manifestBanner + THREE_HELPERS,
    THREE_SERVICES,
    THREE_ACTOR_AND_RUNTIME,
  ].join('\n\n');
  return Object.freeze([Object.freeze({ target: 'three', fileName: 'ashfox-three.ts', content })]);
};

export const THREE_SDK_STRATEGY: SdkTargetStrategy = Object.freeze({
  target: 'three',
  files: emitThreeSdk,
});
